function ObjectiveImage({ objetivo, height = 120 }) {
  const [url, setUrl] = useState(_imageCache["obj_" + objetivo.id] || null);
  const [err, setErr] = useState(false);

  useEffect(() => {
    if (_imageCache["obj_" + objetivo.id]) { setUrl(_imageCache["obj_" + objetivo.id]); return; }
    if (!objetivo.imgQuery) return;
    fetchUnsplashImage(objetivo.imgQuery).then(imgUrl => {
      if (imgUrl) { _imageCache["obj_" + objetivo.id] = imgUrl; setUrl(imgUrl); }
    });
  }, [objetivo.id]);

  if (err || !url) {
    return (
      <div style={{height, background:`linear-gradient(135deg,${objetivo.cor}55,${objetivo.cor}99)`,display:"flex",alignItems:"center",justifyContent:"center"}}>
        <i className={`ti ${objetivo.icon}`} style={{fontSize:48,color:"#fff",opacity:0.9}} aria-hidden="true"></i>
      </div>
    );
  }
  return (
    <img src={url} alt={objetivo.nome} onError={()=>setErr(true)}
      style={{width:"100%",height,objectFit:"cover",display:"block"}}/>
  );
}

async function fetchUnsplashImage(query) {
  try {
    const url = `https://api.unsplash.com/search/photos?query=${encodeURIComponent(query)}&per_page=1&orientation=landscape&client_id=${UNSPLASH_KEY}`;
    const res = await fetch(url, { headers: { "Accept-Version": "v1" } });
    const data = await res.json();
    if (data.results && data.results.length > 0) {
      return data.results[0].urls.small;
    }
  } catch(e) {}
  return null;
}

const _imageCache = {};

function ProductImage({ produto, height = 160 }) {
  const [url, setUrl] = useState(_imageCache[produto.id] || null);
  const [err, setErr] = useState(false);

  useEffect(() => {
    if (_imageCache[produto.id]) { setUrl(_imageCache[produto.id]); return; }
    const query = PRODUCT_QUERIES[produto.id];
    if (!query) return;
    fetchUnsplashImage(query).then(imgUrl => {
      if (imgUrl) { _imageCache[produto.id] = imgUrl; setUrl(imgUrl); }
    });
  }, [produto.id]);

  if (err || !url) {
    return (
      <div style={{height, background:`linear-gradient(135deg,${produto.cor}40,${produto.cor}70)`,display:"flex",alignItems:"center",justifyContent:"center",transition:"all 0.3s"}}>
        <i className={`ti ${produto.icon}`} style={{fontSize:52,color:"#fff",opacity:0.9}} aria-hidden="true"></i>
      </div>
    );
  }
  return (
    <img src={url} alt={produto.nome} onError={()=>setErr(true)}
      style={{width:"100%",height,objectFit:"cover",display:"block",transition:"opacity 0.3s"}}/>
  );
}

