function PaginaObjetivos({ onAbrirObjetivo }) {
  return (
    <div style={{padding:"20px 16px 40px",maxWidth:480,margin:"0 auto"}}>
      <p style={{fontSize:13,color:"#888",marginBottom:20,fontFamily:"Arial,sans-serif",lineHeight:1.5}}>
        Escolha seu objetivo de saúde e veja as combinações de produtos mais indicadas para você.
      </p>
      <div style={{display:"grid",gridTemplateColumns:"repeat(2,minmax(0,1fr))",gap:12}}>
        {OBJETIVOS.map(obj => (
          <div key={obj.id} onClick={()=>onAbrirObjetivo(obj)}
            style={{background:"#fff",borderRadius:16,overflow:"hidden",cursor:"pointer",
              boxShadow:"0 2px 12px rgba(0,0,0,0.07)",
              transition:"transform 0.15s,box-shadow 0.15s"}}
            onMouseEnter={e=>{e.currentTarget.style.transform="translateY(-2px)";e.currentTarget.style.boxShadow="0 6px 20px rgba(0,0,0,0.12)";}}
            onMouseLeave={e=>{e.currentTarget.style.transform="translateY(0)";e.currentTarget.style.boxShadow="0 2px 12px rgba(0,0,0,0.07)";}}>
            <div style={{position:"relative",height:100,overflow:"hidden"}}>
              <ObjectiveImage objetivo={obj} height={100}/>
              <div style={{position:"absolute",inset:0,background:`linear-gradient(to bottom,transparent 20%,rgba(0,0,0,0.55) 100%)`}}></div>
              <div style={{position:"absolute",top:8,left:8,background:obj.cor,borderRadius:20,width:32,height:32,display:"flex",alignItems:"center",justifyContent:"center"}}>
                <i className={`ti ${obj.icon}`} style={{fontSize:17,color:"#fff"}} aria-hidden="true"></i>
              </div>
            </div>
            <div style={{padding:"10px 12px 14px",borderTop:`3px solid ${obj.cor}`}}>
              <div style={{fontSize:14,fontWeight:700,color:"#1A2E0A",marginBottom:4,fontFamily:"Georgia,serif"}}>{obj.nome}</div>
              <div style={{fontSize:11,color:"#888",lineHeight:1.4,fontFamily:"Arial,sans-serif"}}>{obj.produtos.length} produtos recomendados</div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function PaginaObjetivo({ objetivo, onVoltar, onAbrirProduto }) {
  return (
    <div style={{minHeight:"100vh",background:"#F7F5F0",fontFamily:"Georgia,serif"}}>
      <div style={{position:"relative",height:200,overflow:"hidden"}}>
        <ObjectiveImage objetivo={objetivo} height={200}/>
        <div style={{position:"absolute",inset:0,background:`linear-gradient(to bottom,rgba(0,0,0,0.2) 0%,${objetivo.cor}EE 80%)`}}></div>
        <div style={{position:"absolute",inset:0,padding:"18px 20px 20px",display:"flex",flexDirection:"column",justifyContent:"space-between"}}>
          <button onClick={onVoltar} style={{alignSelf:"flex-start",background:"rgba(255,255,255,0.22)",border:"none",borderRadius:50,padding:"7px 16px",color:"#fff",cursor:"pointer",fontSize:13,fontFamily:"Arial,sans-serif",display:"flex",alignItems:"center",gap:5}}>
            <i className="ti ti-arrow-left" style={{fontSize:15}} aria-hidden="true"></i>Objetivos
          </button>
          <div>
            <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:8}}>
              <div style={{width:36,height:36,background:"rgba(255,255,255,0.22)",borderRadius:10,display:"flex",alignItems:"center",justifyContent:"center"}}>
                <i className={`ti ${objetivo.icon}`} style={{fontSize:20,color:"#fff"}} aria-hidden="true"></i>
              </div>
              <h1 style={{fontSize:26,fontWeight:700,color:"#fff",margin:0,lineHeight:1.2,textShadow:"0 1px 4px rgba(0,0,0,0.3)"}}>{objetivo.nome}</h1>
            </div>
            <p style={{fontSize:13,color:"rgba(255,255,255,0.88)",margin:0,lineHeight:1.55,fontFamily:"Arial,sans-serif"}}>{objetivo.descricao}</p>
          </div>
        </div>
      </div>

      <div style={{padding:"16px 18px 44px",maxWidth:480,margin:"0 auto"}}>
        <div style={{background:objetivo.bg,borderRadius:14,padding:"14px 16px",borderLeft:`4px solid ${objetivo.cor}`,marginBottom:20}}>
          <div style={{fontSize:10,fontWeight:700,color:objetivo.cor,textTransform:"uppercase",letterSpacing:1,fontFamily:"Arial,sans-serif",marginBottom:6}}>
            <i className="ti ti-bulb" style={{marginRight:5}} aria-hidden="true"></i>Dica do especialista
          </div>
          <div style={{fontSize:13,color:"#444",lineHeight:1.6,fontFamily:"Arial,sans-serif"}}>{objetivo.dica}</div>
        </div>

        <div style={{fontSize:13,fontWeight:700,color:"#555",textTransform:"uppercase",letterSpacing:1,fontFamily:"Arial,sans-serif",marginBottom:14}}>
          Produtos Recomendados
        </div>

        {objetivo.produtos.map((item, i) => {
          const prod = PRODUCTS.find(p => p.id === item.id);
          if (!prod) return null;
          const isPrincipal = item.papel.includes("⭐");
          return (
            <div key={i} style={{background:"#fff",borderRadius:14,marginBottom:12,overflow:"hidden",
              boxShadow:isPrincipal?"0 3px 14px rgba(0,0,0,0.10)":"0 2px 8px rgba(0,0,0,0.06)",
              border:isPrincipal?`2px solid ${objetivo.cor}22`:"2px solid transparent"}}>
              <div style={{height:isPrincipal?90:70,overflow:"hidden",position:"relative"}}>
                <ProductImage produto={prod} height={isPrincipal?90:70}/>
                <div style={{position:"absolute",inset:0,background:`linear-gradient(to right,${prod.cor}EE 0%,${prod.cor}88 45%,transparent 100%)`}}></div>
                <div style={{position:"absolute",inset:0,padding:"0 14px",display:"flex",alignItems:"center",gap:10}}>
                  <div style={{width:34,height:34,background:"rgba(255,255,255,0.22)",borderRadius:9,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                    <i className={`ti ${prod.icon}`} style={{fontSize:18,color:"#fff"}} aria-hidden="true"></i>
                  </div>
                  <div>
                    <div style={{fontWeight:700,fontSize:15,color:"#fff",fontFamily:"Georgia,serif"}}>{prod.nome}</div>
                    <div style={{fontSize:11,color:"rgba(255,255,255,0.85)",fontFamily:"Arial,sans-serif",fontWeight:600}}>{item.papel}</div>
                  </div>
                </div>
              </div>
              <div style={{padding:"10px 14px 12px"}}>
                <div style={{fontSize:12,color:"#555",lineHeight:1.6,fontFamily:"Arial,sans-serif",marginBottom:8}}>{item.motivo}</div>
                <button onClick={()=>onAbrirProduto(prod)}
                  style={{width:"100%",background:objetivo.bg,border:`1px solid ${objetivo.cor}44`,borderRadius:9,padding:"7px 0",fontSize:11,color:objetivo.cor,cursor:"pointer",fontFamily:"Arial,sans-serif",fontWeight:700}}>
                  Ver produto completo →
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function PaginaCatalogo({ produtos, busca, setBusca, categoriaAtiva, setCategoriaAtiva, onAbrirProduto }) {
  return (
    <div style={{background:"#F7F5F0",fontFamily:"Georgia,serif"}}>
      <div style={{padding:"14px 16px 6px",overflowX:"auto",whiteSpace:"nowrap",maxWidth:480,margin:"0 auto"}}>
        {CATEGORIAS.map(cat=>(
          <button key={cat} onClick={()=>setCategoriaAtiva(cat)}
            style={{display:"inline-block",marginRight:7,padding:"6px 14px",borderRadius:50,fontSize:12,border:"none",cursor:"pointer",fontFamily:"Arial,sans-serif",fontWeight:600,
              background:categoriaAtiva===cat?"#4A5C2E":"#fff",color:categoriaAtiva===cat?"#fff":"#4A5C2E",
              boxShadow:categoriaAtiva===cat?"0 2px 8px rgba(74,92,46,0.3)":"0 1px 4px rgba(0,0,0,0.08)"}}>
            {cat}
          </button>
        ))}
      </div>
      <div style={{padding:"8px 16px 40px",maxWidth:480,margin:"0 auto"}}>
        <div style={{fontSize:12,color:"#999",marginBottom:10,fontFamily:"Arial,sans-serif"}}>{produtos.length} {produtos.length===1?"produto":"produtos"}</div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(2,minmax(0,1fr))",gap:12}}>
          {produtos.map(prod=>(
            <div key={prod.id} onClick={()=>onAbrirProduto(prod)}
              style={{background:"#fff",borderRadius:16,overflow:"hidden",cursor:"pointer",boxShadow:"0 2px 12px rgba(0,0,0,0.07)"}}>
              <div style={{position:"relative",height:110,overflow:"hidden"}}>
                <ProductImage produto={prod} height={110}/>
                <div style={{position:"absolute",bottom:0,left:0,right:0,height:40,background:`linear-gradient(transparent,${prod.cor}CC)`}}></div>
                <div style={{position:"absolute",top:8,right:8,background:prod.cor,borderRadius:20,padding:"3px 8px"}}>
                  <span style={{fontSize:10,color:"#fff",fontWeight:700,textTransform:"uppercase",letterSpacing:0.5,fontFamily:"Arial,sans-serif"}}>{prod.categoria}</span>
                </div>
              </div>
              <div style={{padding:"10px 12px 14px"}}>
                <div style={{fontSize:14,fontWeight:700,color:"#1A2E0A",marginBottom:5,fontFamily:"Georgia,serif"}}>{prod.nome}</div>
                <div style={{fontSize:11,color:"#777",lineHeight:1.5,fontFamily:"Arial,sans-serif",display:"-webkit-box",WebkitLineClamp:2,WebkitBoxOrient:"vertical",overflow:"hidden"}}>{prod.descricao}</div>
              </div>
            </div>
          ))}
        </div>
        {produtos.length===0&&(
          <div style={{textAlign:"center",padding:"48px 24px",color:"#bbb",fontFamily:"Arial,sans-serif"}}>
            <i className="ti ti-search-off" style={{fontSize:44,display:"block",marginBottom:10}} aria-hidden="true"></i>
            Nenhum produto encontrado
          </div>
        )}
      </div>
    </div>
  );
}

function PaginaProduto({ produto, onVoltar, onAbrirProduto, abaAtiva, setAbaAtiva }) {
  const abas = [
    {id:"como-age",label:"Como age",icon:"ti-dna"},
    {id:"beneficios",label:"Benefícios",icon:"ti-heart"},
    {id:"como-usar",label:"Como usar",icon:"ti-tool"},
    {id:"combina",label:"Combina com",icon:"ti-circles"}
  ];
  return (
    <div style={{minHeight:"100vh",background:"#F7F5F0",fontFamily:"Georgia,serif"}}>
      <div style={{position:"relative",height:220,overflow:"hidden"}}>
        <ProductImage produto={produto} height={220}/>
        <div style={{position:"absolute",inset:0,background:`linear-gradient(to bottom, rgba(0,0,0,0.15) 0%, ${produto.cor}EE 85%)`}}></div>
        <div style={{position:"absolute",inset:0,padding:"18px 20px 20px",display:"flex",flexDirection:"column",justifyContent:"space-between"}}>
          <button onClick={onVoltar} style={{alignSelf:"flex-start",background:"rgba(255,255,255,0.22)",border:"none",borderRadius:50,padding:"7px 16px",color:"#fff",cursor:"pointer",fontSize:13,fontFamily:"Arial,sans-serif",display:"flex",alignItems:"center",gap:5}}>
            <i className="ti ti-arrow-left" style={{fontSize:15}} aria-hidden="true"></i>Catálogo
          </button>
          <div>
            <div style={{fontSize:10,color:"rgba(255,255,255,0.75)",textTransform:"uppercase",letterSpacing:2,fontFamily:"Arial,sans-serif",marginBottom:4}}>{produto.categoria}</div>
            <h1 style={{fontSize:26,fontWeight:700,color:"#fff",margin:"0 0 6px",lineHeight:1.2,textShadow:"0 1px 4px rgba(0,0,0,0.3)"}}>{produto.nome}</h1>
            <p style={{fontSize:13,color:"rgba(255,255,255,0.88)",margin:0,lineHeight:1.55,fontFamily:"Arial,sans-serif"}}>{produto.descricao}</p>
          </div>
        </div>
      </div>
      <div style={{display:"flex",background:"#fff",borderBottom:"1px solid #eee",position:"sticky",top:0,zIndex:90}}>
        {abas.map(aba=>(
          <button key={aba.id} onClick={()=>setAbaAtiva(aba.id)}
            style={{flex:1,padding:"13px 6px",border:"none",background:"transparent",cursor:"pointer",
              borderBottom:abaAtiva===aba.id?`3px solid ${produto.cor}`:"3px solid transparent",
              color:abaAtiva===aba.id?produto.cor:"#aaa",
              fontFamily:"Arial,sans-serif",fontSize:10,fontWeight:700,textTransform:"uppercase",letterSpacing:0.5,
              display:"flex",flexDirection:"column",alignItems:"center",gap:3}}>
            <i className={`ti ${aba.icon}`} style={{fontSize:17}} aria-hidden="true"></i>
            {aba.label}
          </button>
        ))}
      </div>
      <div style={{padding:"20px 18px 44px",maxWidth:480,margin:"0 auto"}}>
        {abaAtiva==="como-age"&&(
          <div>
            <h2 style={{fontSize:19,color:"#1A2E0A",marginBottom:14}}>Como age no organismo</h2>
            <div style={{background:"#fff",borderRadius:14,padding:18,boxShadow:"0 2px 10px rgba(0,0,0,0.06)",borderLeft:`4px solid ${produto.cor}`,marginBottom:14}}>
              <p style={{fontSize:14,lineHeight:1.85,color:"#444",margin:0,fontFamily:"Arial,sans-serif"}}>{produto.comoAge}</p>
            </div>
            <div style={{background:`${produto.cor}0E`,borderRadius:14,padding:18,border:`1px solid ${produto.cor}20`}}>
              <div style={{fontSize:11,fontWeight:700,color:produto.cor,textTransform:"uppercase",letterSpacing:1,fontFamily:"Arial,sans-serif",marginBottom:10}}>Diferenciais do nosso produto</div>
              {produto.diferenciais.map((d,i)=>(
                <div key={i} style={{display:"flex",gap:10,marginBottom:10,alignItems:"flex-start"}}>
                  <i className="ti ti-check" style={{fontSize:15,color:produto.cor,flexShrink:0,marginTop:2}} aria-hidden="true"></i>
                  <span style={{fontSize:13,color:"#555",lineHeight:1.5,fontFamily:"Arial,sans-serif"}}>{d}</span>
                </div>
              ))}
            </div>
          </div>
        )}
        {abaAtiva==="beneficios"&&(
          <div>
            <h2 style={{fontSize:19,color:"#1A2E0A",marginBottom:14}}>Benefícios comprovados</h2>
            <div style={{display:"grid",gridTemplateColumns:"repeat(2,minmax(0,1fr))",gap:10}}>
              {produto.beneficios.map((b,i)=>(
                <div key={i} style={{background:"#fff",borderRadius:12,padding:"14px 12px",boxShadow:"0 2px 8px rgba(0,0,0,0.05)",borderTop:`3px solid ${produto.cor}`}}>
                  <i className="ti ti-heart" style={{fontSize:17,color:produto.cor,display:"block",marginBottom:7}} aria-hidden="true"></i>
                  <span style={{fontSize:12,color:"#555",lineHeight:1.4,fontFamily:"Arial,sans-serif"}}>{b}</span>
                </div>
              ))}
            </div>
          </div>
        )}
        {abaAtiva==="como-usar"&&(
          <div>
            <h2 style={{fontSize:19,color:"#1A2E0A",marginBottom:14}}>Como usar da melhor forma</h2>
            {produto.comoUsar.map((uso,i)=>(
              <div key={i} style={{display:"flex",gap:12,marginBottom:10,background:"#fff",borderRadius:12,padding:14,boxShadow:"0 2px 8px rgba(0,0,0,0.05)",alignItems:"flex-start"}}>
                <div style={{width:26,height:26,background:`${produto.cor}20`,borderRadius:"50%",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                  <span style={{fontSize:12,fontWeight:700,color:produto.cor,fontFamily:"Arial,sans-serif"}}>{i+1}</span>
                </div>
                <span style={{fontSize:13,color:"#444",lineHeight:1.6,fontFamily:"Arial,sans-serif"}}>{uso}</span>
              </div>
            ))}
          </div>
        )}
        {abaAtiva==="combina"&&(
          <div>
            <h2 style={{fontSize:19,color:"#1A2E0A",marginBottom:6}}>Combina com</h2>
            <p style={{fontSize:12,color:"#999",marginBottom:18,fontFamily:"Arial,sans-serif"}}>Esses produtos potencializam os efeitos — ofereça sempre!</p>
            {produto.combinacoes.map((comb,i)=>{
              const rel=PRODUCTS.find(p=>p.nome===comb.produto);
              return(
                <div key={i} style={{background:"#fff",borderRadius:14,marginBottom:12,boxShadow:"0 2px 10px rgba(0,0,0,0.06)",overflow:"hidden"}}>
                  {rel&&<div style={{height:80,overflow:"hidden",position:"relative"}}>
                    <ProductImage produto={rel} height={80}/>
                    <div style={{position:"absolute",inset:0,background:`linear-gradient(to right,${rel.cor}EE 0%,${rel.cor}88 50%,transparent 100%)`}}></div>
                    <div style={{position:"absolute",inset:0,padding:"0 14px",display:"flex",alignItems:"center",gap:10}}>
                      <div style={{width:36,height:36,background:"rgba(255,255,255,0.22)",borderRadius:10,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                        <i className={`ti ${rel.icon}`} style={{fontSize:20,color:"#fff"}} aria-hidden="true"></i>
                      </div>
                      <div style={{fontWeight:700,fontSize:15,color:"#fff",fontFamily:"Georgia,serif",textShadow:"0 1px 3px rgba(0,0,0,0.3)"}}>{comb.produto}</div>
                    </div>
                  </div>}
                  <div style={{padding:"12px 14px 14px"}}>
                    <div style={{fontSize:12,color:"#666",lineHeight:1.6,fontFamily:"Arial,sans-serif",marginBottom:10}}>{comb.motivo}</div>
                    <div style={{background:`${produto.cor}12`,borderRadius:9,padding:"9px 13px",borderLeft:`3px solid ${produto.cor}`}}>
                      <div style={{fontSize:9,fontWeight:700,color:produto.cor,textTransform:"uppercase",letterSpacing:1,fontFamily:"Arial,sans-serif",marginBottom:4}}>Frase para usar na venda</div>
                      <div style={{fontSize:12,color:"#444",fontStyle:"italic",lineHeight:1.5,fontFamily:"Georgia,serif"}}>"{comb.script}"</div>
                    </div>
                    {rel&&<button onClick={()=>onAbrirProduto(rel)}
                      style={{marginTop:10,width:"100%",background:"transparent",border:`1px solid ${rel.cor}44`,borderRadius:9,padding:"8px 0",fontSize:11,color:rel.cor,cursor:"pointer",fontFamily:"Arial,sans-serif",fontWeight:600}}>
                      Ver {comb.produto} completo
                    </button>}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

export default App;
